/* Actual app06 base ability/PB derivation plus actual Customize and saved-Ioun review. */
import fs from'node:fs';import vm from'node:vm';import{iounCharacterMathStatus}from'../../src/data/lib/ioun-orbit-source.js';
const read=p=>fs.readFileSync(new URL('../../src/app/'+p,import.meta.url),'utf8'),line=(s,prefix)=>{const rows=s.split('\n').filter(s=>s.startsWith(prefix));if(rows.length!==1)throw Error('Actual stat helper missing '+prefix);return rows[0].replace('export ','')};
export function installNativeCastingStats(host){const ctx={};ctx.lateGet=k=>ctx[k];ctx.lateSet=(k,v)=>ctx[k]=v;vm.createContext(ctx);const helpers=read('05-logic-helpers.js');for(const n of ['num','clamp','sg','mod'])vm.runInContext(line(helpers,'export function '+n+'('),ctx);const constants=read('02-data-default-character.js');for(const n of ['ABK','ABN'])vm.runInContext(line(constants,'export var '+n+' ='),ctx);vm.runInContext(line(read('03-data-glossary.js'),'export function x14('),ctx);const app=read('06-logic-derivation.js'),a=app.indexOf('function deriveBase(){'),b=app.indexOf('function deriveSaves(',a);vm.runInContext('var D={},B={};'+line(app,'export function part(')+'\n'+app.slice(a,b),ctx);const custom=read('26-ui-customize.js'),ca=custom.indexOf('export function cuK('),cb=custom.indexOf('function cuSpeed(',ca);vm.runInContext(custom.slice(ca,cb).replace(/^export /gm,''),ctx);host.genv.__deriveFor=(character,state)=>{ctx.C=structuredClone(character);ctx.S=structuredClone(state);ctx.deriveBase();return {...structuredClone(ctx.D),sourceReview:iounCharacterMathStatus(character,state)}};return host.genv.__deriveFor;}
